// Applies the SQL migrations in database/migrations (generated by `npm run db:generate`).
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/mysql2/migrator';
import { db, pool } from './db.js';
import { logger } from '../utils/logger.js';

const folder = path.join(path.dirname(fileURLToPath(import.meta.url)), '../../database/migrations');

/**
 * Tables take the database's default character set. Arabic text and emoji need utf8mb4,
 * so switch the default before any table is created (some hosts create databases as latin1).
 */
async function ensureUtf8mb4() {
  const [[row]] = await pool.query('select @@character_set_database as cs, database() as name');
  if (row.cs === 'utf8mb4') return;
  await pool.query(`alter database \`${row.name}\` character set utf8mb4 collate utf8mb4_unicode_ci`);
  logger.warn(`Database default character set changed from ${row.cs} to utf8mb4.`);
}

export async function runMigrations() {
  await ensureUtf8mb4();
  await migrate(db, { migrationsFolder: folder });
}
